import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"权限与脱敏（前端）","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/permission.md","filePath":"frontend/permission.md","lastUpdated":1786258579000}'),o={name:"frontend/permission.md"};function d(n,s,r,c,l,h){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="权限与脱敏-前端" tabindex="-1">权限与脱敏（前端） <a class="header-anchor" href="#权限与脱敏-前端" aria-label="Permalink to &quot;权限与脱敏（前端）&quot;">​</a></h1><p>前端在<strong>页面 / 字段 / 操作</strong>三个层级按权限码过滤，并在服务端脱敏的基础上做只读与标识提示。本页讲前端这一侧怎么写；判定规则本身（权限码、数据范围、ABAC、约束规则）见 <a href="./../backend/permission">权限模型</a>。</p><h2 id="前提-前端过滤是体验-不是安全边界" tabindex="-1">前提：前端过滤是体验，不是安全边界 <a class="header-anchor" href="#前提-前端过滤是体验-不是安全边界" aria-label="Permalink to &quot;前提：前端过滤是体验，不是安全边界&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">服务端才是安全边界</p><p>前端隐藏按钮只是<strong>不让用户看到无效入口</strong>。真正的门控在服务端：<code>[PermissionAuthorize]</code> 特性 + 授权快照判定。</p><p>绕过前端直接调接口一定会被后端拒绝——所以<strong>不要因为前端已经隐藏了按钮就省掉后端的权限标注</strong>。</p></div><h2 id="权限码" tabindex="-1">权限码 <a class="header-anchor" href="#权限码" aria-label="Permalink to &quot;权限码&quot;">​</a></h2><p>以 <code>:</code> 分段，多数是 <code>module:resource:action</code>（如 <code>saas:user:read</code>、<code>saas:tenant-edition-permission:grant</code>），也有两段的 <code>module:action</code>（如 <code>workflow:execute</code>）。超管用<strong>字面通配 <code>*</code></strong>（不是段级 <code>*:*:*</code>）。</p><p><strong>真源在后端</strong> <code>SaasPermissionDefinitions</code>（Saas 模块）与各模块自己的权限码类。前端只是消费者——写权限码字符串时去后端对一下，别凭记忆写。</p><p>用户的权限码集合来自登录后的 <code>GET /api/Auth/Permissions</code>。</p><div class="tip custom-block"><p class="custom-block-title">权限码不在 JWT 里</p><p>Access Token 里没有具体权限码（超管例外，只放一个 <code>*</code> 作快路径）。这带来一个好性质：<strong>管理员改了授权，用户不用重新登录就生效</strong>——前端下次拉取权限或后端下次判定时就是新的。</p></div><h2 id="三级过滤" tabindex="-1">三级过滤 <a class="header-anchor" href="#三级过滤" aria-label="Permalink to &quot;三级过滤&quot;">​</a></h2><h3 id="一、页面级" tabindex="-1">一、页面级 <a class="header-anchor" href="#一、页面级" aria-label="Permalink to &quot;一、页面级&quot;">​</a></h3><p>由路由守卫按 <code>meta.roles</code> / <code>meta.permissions</code> 校验，无权跳 403。数据来自后端 <code>PageDescriptor.PermissionCode</code>。</p><p><code>PermissionCode</code> 为空的页面是<strong>纯展示菜单</strong>，不做门控。</p><h3 id="二、字段级" tabindex="-1">二、字段级 <a class="header-anchor" href="#二、字段级" aria-label="Permalink to &quot;二、字段级&quot;">​</a></h3><p>Schema 页里字段声明 <code>permission</code>，<strong>无权时该列与该搜索项整个不渲染</strong>（<code>selectors.ts</code> 的 <code>isFieldPermitted</code>）：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;phone&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;identity.org.col_phone&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dataType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;string&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;saas:department:read&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>注意这是「<strong>不渲染</strong>」而不是「渲染成空」——用户看不到这一列存在。</p><h3 id="三、操作级" tabindex="-1">三、操作级 <a class="header-anchor" href="#三、操作级" aria-label="Permalink to &quot;三、操作级&quot;">​</a></h3><ul><li>Schema 页的 <code>actions[].permission</code>：无权时按钮不出现。</li><li><code>PageSchema</code> 上的 <code>exportPermission</code> / <code>importPermission</code> / <code>removePermission</code>（批量删除）/ <code>statusPermission</code>（批量启停）：门控对应的内置按钮。其中只有 <code>exportPermission</code> 是<strong>严格门控</strong>（未声明就不显示导出），另外三个未声明时不做限制。</li></ul><div class="warning custom-block"><p class="custom-block-title"><code>exportPermission</code> 未声明 = 不显示导出</p><p>这是刻意的默认值选择：宁可漏显示，不可错显示。要导出按钮就必须声明权限码。</p></div><h3 id="页面里手写门控" tabindex="-1">页面里手写门控 <a class="header-anchor" href="#页面里手写门控" aria-label="Permalink to &quot;页面里手写门控&quot;">​</a></h3><p>没有包裹式权限组件——页面按钮/区块级门控统一是「<code>usePermission()</code> 派生 computed + 模板 <code>v-if</code>」这一种写法：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hasPermission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usePermission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> canGrant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hasPermission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;saas:tenant-edition-permission:grant&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">NButton</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> v-if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">canGrant</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;分配权限&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">NButton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>usePermission()</code>（<code>~/hooks/usePermission.ts</code>）提供：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>hasPermission(code | code[])</code></td><td>是否有权限码（传数组时任一命中即通过）</td></tr><tr><td><code>hasRole(role | role[])</code></td><td>是否有角色（传数组时任一命中即通过）</td></tr><tr><td><code>hasAnyPermission(codes[])</code></td><td>任一命中即通过</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">统一用这一种写法</p><p>不要另造包裹组件或指令。全仓统一「computed + <code>v-if</code>」的好处是：审计权限点时一个 grep 就能找全，也不会出现「指令生效时机与渲染时机不一致」的坑。</p></div><h2 id="字段级脱敏-fls" tabindex="-1">字段级脱敏（FLS） <a class="header-anchor" href="#字段级脱敏-fls" aria-label="Permalink to &quot;字段级脱敏（FLS）&quot;">​</a></h2><h3 id="脱敏在服务端完成" tabindex="-1">脱敏在服务端完成 <a class="header-anchor" href="#脱敏在服务端完成" aria-label="Permalink to &quot;脱敏在服务端完成&quot;">​</a></h3><p><strong>后端返回的敏感字段已经是打码后的值</strong>（如 <code>138****8000</code>），前端<strong>不再二次打码</strong>。</p><p>前端侧的 <code>useFieldSecurity(resourceCode)</code>（<code>~/components/schema/useFieldSecurity.ts</code>）由页面自行调用：传入后端资源码，再调 <code>resolve()</code> 拉取当前用户在该资源上的有效字段规则（<code>GET /MyFieldSecurity/Mine?resourceCode=</code>）。它返回 <code>ruleFor</code> / <code>isReadable</code> / <code>isEditable</code> / <code>resolve</code>，用途只有两个：</p><ol><li>表单按 <code>isEditable(fieldKey)</code> 置<strong>只读</strong>；</li><li>展示「不可见 / 已脱敏」的<strong>标识</strong>。</li></ol><p>规则形如：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ fieldName, isReadable, isEditable, maskStrategy, maskPattern }</span></span></code></pre></div><p>端点未就绪或无规则时<strong>默认放行</strong>（<code>isReadable</code> / <code>isEditable</code> 缺省 <code>true</code>）。</p><div class="warning custom-block"><p class="custom-block-title"><code>SchemaPage</code> 不会自动接线 FLS</p><p><code>useFieldSecurity</code> 是独立 hook，<code>SchemaPage</code> 不会自动调用它——<code>PageSchema.resourceCode</code> 只用于导入留痕。要按 FLS 置只读，得在页面里自己 <code>useFieldSecurity(...)</code> + <code>resolve()</code> 并把 <code>isEditable</code> 接到表单上。</p></div><h3 id="fls-也门控过滤与排序" tabindex="-1">FLS 也门控过滤与排序 <a class="header-anchor" href="#fls-也门控过滤与排序" aria-label="Permalink to &quot;FLS 也门控过滤与排序&quot;">​</a></h3><p>服务端读侧会经 <code>GuardFiltersAsync</code> / <code>GuardSortsAsync</code> 剔除<strong>不可读或已脱敏</strong>字段的过滤与排序条件，剔完没有有效排序时回退默认排序。</p><p>所以「排序点了没反应」「按某字段搜索没效果」优先怀疑字段权限，而不是前端 bug。</p><h2 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h2><p>数据按 <code>TenantId</code> 隔离，全局数据约定 <code>TenantId=0</code>。<strong>前端不需要手动处理租户过滤</strong>——它由后端在请求管道里完成，前端只按拿到的权限码集合渲染。</p><p>前端要处理的只有两件事：</p><table tabindex="0"><thead><tr><th>事情</th><th>说明</th></tr></thead><tbody><tr><td>租户切换</td><td>调 <code>POST /api/Auth/SwitchTenant</code>（<code>tenantId</code> 传 <code>null</code> 回平台态），<strong>换发令牌但不产生新登录/新设备</strong></td></tr><tr><td>平台态判断</td><td><code>UserInfo.isPlatform</code>（当前是否平台运维态）、<code>canAccessPlatform</code>（能否进入）</td></tr></tbody></table><p>切换后要重新拉取权限与菜单——租户不同，可用的功能也不同（受<a href="./../backend/multi-tenancy">租户版本门控</a>影响）。</p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>按钮不显示</td><td>权限码写错（去后端 <code>SaasPermissionDefinitions</code> 对）；或用户确实没这个权限</td></tr><tr><td>导出按钮不显示</td><td><code>PageSchema.exportPermission</code> 没声明</td></tr><tr><td>列不显示</td><td>字段 <code>permission</code> 无权；或 <code>visible: false</code></td></tr><tr><td>表单该只读却可编辑</td><td>页面没调 <code>useFieldSecurity(...)</code> + <code>resolve()</code>，或没把 <code>isEditable</code> 接到表单字段上</td></tr><tr><td>前端能点、后端 403</td><td>正常——前端过滤是体验层，以后端为准。检查该接口的 <code>[PermissionAuthorize]</code> 是否与前端用的码一致</td></tr><tr><td>改了授权前端还是旧的</td><td>重新拉 <code>/api/Auth/Permissions</code>；后端侧检查是否调了 <code>InvalidateAuthorizationAsync</code></td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../backend/permission">权限模型</a>：权限码、RBAC 继承、数据范围、ABAC、约束规则</li><li><a href="./schema-page">Schema 驱动页面</a>：字段与操作的权限声明位置</li><li><a href="./routing">路由与菜单</a>：页面级门控</li><li><a href="./../backend/multi-tenancy">多租户与版本</a>：版本门控与租户切换</li></ul>`,48)])])}const g=e(o,[["render",d]]);export{k as __pageData,g as default};
